llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "In fasted healthy volunteers, standard Sinemet (levodopa/carbidopa) had a mean absolute oral bioavailability of 80.4%, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "In healthy young subjects, the active metabolite of nabumetone had a mean absolute bioavailability of 38% after a 1000 mg oral dose, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Metoclopramide oral bioavailability was 60% in normal patients, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Meperidine oral bioavailability in healthy young men was 47–73% versus IV, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Diflunisal tablet AUC was about 89.5% of the parenteral AUC, indicating high absolute oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Oral lemborexant was at least 87% bioavailable in healthy subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental records, across diverse chemical scaffolds and with very high transfer scores, report absolute oral bioavailability values above 20% (approximately 26–99%). No retrieved evidence supports F < 20%. The query's small, moderately lipophilic, weakly basic structure is consistent with good oral absorption, so the prediction is high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself.",
    "Some records describe co-formulated drugs, prodrugs, or active metabolites rather than the exact analogue SMILES, introducing minor uncertainty in transfer.",
    "The retrieved set contains no low-bioavailability comparator, so the high prediction is not challenged by negative evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

